import { dataRefLabel, resourceRefLabel } from "../../engine/pull/context.js";
import { scopedLabelToBagKey, tfLabelToTsLabel } from "../../engine/tf/index.js";
import { serviceAccountRoleRef, serviceAccountStatus, } from "./build.js";
import { SERVICE_ACCOUNT_ACCESS_POLICY_RESOURCE_TYPE, SERVICE_ACCOUNT_RESOURCE_TYPE } from "./module.js";
const ACCOUNT_ATTRS = new Set(["id", "app_id", "first_name", "last_name", "purpose", "name", "status", "role_ids"]);
const POLICY_ATTRS = new Set(["id", "app_id", "service_account_id", "user_ids", "group_ids"]);
function principal(value, type, where, ctx) {
    const label = dataRefLabel(value, type);
    if (label !== undefined) {
        const name = ctx.dataName(type, label);
        if (name !== undefined) {
            if (type === "elementum_user") {
                if (name.trim() === "" || !name.includes("@")) {
                    ctx.diagnostics.push(`${where}: data.${type}.${label} has invalid email ${JSON.stringify(name)}; dropped`);
                    return undefined;
                }
                return { __kind: "user", email: name.trim() };
            }
            return { __kind: "group", refName: tfLabelToTsLabel(label), name };
        }
        ctx.diagnostics.push(`${where}: data.${type}.${label} has no lookup value; dropped`);
        return undefined;
    }
    if (typeof value === "string")
        ctx.diagnostics.push(`${where}: raw platform ids are not part of the public EDK API; dropped`);
    else
        ctx.diagnostics.push(`${where}: unrecognized principal; dropped`);
    return undefined;
}
function principalList(value, type, where, ctx) {
    if (value === undefined)
        return undefined;
    if (!Array.isArray(value)) {
        ctx.diagnostics.push(`${where}: expected a list; dropped`);
        return undefined;
    }
    const out = value.flatMap((item) => (type === "elementum_user"
        ? principal(item, "elementum_user", where, ctx)
        : principal(item, "elementum_group", where, ctx)) ?? []);
    return out.length > 0 ? out : undefined;
}
function roleRefs(value, blocks, where, ctx) {
    if (value === undefined)
        return undefined;
    if (!Array.isArray(value)) {
        ctx.diagnostics.push(`${where}: expected a list; dropped`);
        return undefined;
    }
    const out = [];
    for (const item of value) {
        const resourceLabel = resourceRefLabel(item, "elementum_role");
        if (resourceLabel !== undefined) {
            const role = blocks.find((candidate) => candidate.type === "elementum_role" && candidate.label === resourceLabel);
            if (typeof role?.attrs["name"] === "string")
                out.push(serviceAccountRoleRef(role.attrs["name"]));
            else
                ctx.diagnostics.push(`${where}: ${resourceLabel} has no recoverable role name; dropped`);
            continue;
        }
        const dataLabel = dataRefLabel(item, "elementum_role");
        const name = dataLabel === undefined ? undefined : ctx.dataName("elementum_role", dataLabel);
        if (name !== undefined)
            out.push(serviceAccountRoleRef(name));
        else
            ctx.diagnostics.push(`${where}: role reference has no recoverable name; dropped`);
    }
    return out.length > 0 ? out : undefined;
}
export function serviceAccountsFromTf(blocks, owner, ctx) {
    const accounts = blocks.filter((block) => block.type === SERVICE_ACCOUNT_RESOURCE_TYPE);
    const policies = blocks.filter((block) => block.type === SERVICE_ACCOUNT_ACCESS_POLICY_RESOURCE_TYPE);
    return accounts.flatMap((block) => {
        const label = block.label ?? "";
        const where = `${SERVICE_ACCOUNT_RESOURCE_TYPE}.${label || "?"}`;
        if (label === "" || resourceRefLabel(block.attrs["app_id"], "elementum_app") !== owner.label)
            return [];
        for (const attr of Object.keys(block.attrs))
            if (!ACCOUNT_ATTRS.has(attr))
                ctx.diagnostics.push(`${where}: unhandled attribute ${JSON.stringify(attr)}`);
        const firstName = block.attrs["first_name"];
        const lastName = block.attrs["last_name"];
        const purpose = block.attrs["purpose"];
        if (typeof firstName !== "string" || typeof lastName !== "string" || typeof purpose !== "string") {
            ctx.diagnostics.push(`${where}: first_name, last_name, and purpose are required; skipped`);
            return [];
        }
        const accessPolicies = [];
        for (const policy of policies) {
            if (resourceRefLabel(policy.attrs["service_account_id"], SERVICE_ACCOUNT_RESOURCE_TYPE) !== label)
                continue;
            const policyWhere = `${SERVICE_ACCOUNT_ACCESS_POLICY_RESOURCE_TYPE}.${policy.label ?? "?"}`;
            for (const attr of Object.keys(policy.attrs))
                if (!POLICY_ATTRS.has(attr))
                    ctx.diagnostics.push(`${policyWhere}: unhandled attribute ${JSON.stringify(attr)}`);
            if (resourceRefLabel(policy.attrs["app_id"], "elementum_app") !== owner.label) {
                ctx.diagnostics.push(`${policyWhere}: app_id has the wrong owner; skipped`);
                continue;
            }
            const users = principalList(policy.attrs["user_ids"], "elementum_user", `${policyWhere}.user_ids`, ctx);
            const groups = principalList(policy.attrs["group_ids"], "elementum_group", `${policyWhere}.group_ids`, ctx);
            accessPolicies.push({ ...(users !== undefined && { users }), ...(groups !== undefined && { groups }) });
        }
        const roles = roleRefs(block.attrs["role_ids"], blocks, `${where}.role_ids`, ctx);
        const status = block.attrs["status"];
        return [{
                key: scopedLabelToBagKey(owner.ownerTfLabel, label, "app"),
                firstName,
                lastName,
                purpose,
                ...(status === "ACTIVE" ? { status: serviceAccountStatus.active } : status === "INACTIVE" ? { status: serviceAccountStatus.inactive } : {}),
                ...(roles !== undefined && { roles }),
                ...(accessPolicies.length > 0 && { accessPolicies }),
            }];
    });
}
